export const componentNames = {
  L: "Lecture",
  T: "Tutorial",
  P: "Practical",
  S: "Skill",
};

export const initialSelections = {};

/**
 * Returns faculty options for a specific subject, component, cluster, and optional section filter.
 * Strictly sorted by Section Number in ascending order.
 * Displays Section Number, Faculty Name, and Emp ID.
 */
export function getFacultyOptionsForSubject(subjectCode, component = "L", cluster = null, sectionFilter = null) {
  if (!subjectCode) return [];
  const normalizedCluster = cluster === "Cluster 1" || cluster === "C1" ? "Cluster-1" :
                            cluster === "Cluster 2" || cluster === "C2" ? "Cluster-2" : cluster;

  // Normalize sectionFilter if passed as string (e.g. "S21-S25" or "S-21") or array
  let allowedSectionNumbers = null;
  if (sectionFilter) {
    if (Array.isArray(sectionFilter)) {
      allowedSectionNumbers = new Set(sectionFilter.map(s => parseInt(String(s).replace(/\D/g, ''), 10)).filter(Boolean));
    } else if (typeof sectionFilter === 'string' && sectionFilter !== 'NA') {
      const clean = sectionFilter.replace(/S-?/gi, '').trim();
      if (clean.includes('-')) {
        const parts = clean.split('-').map(p => parseInt(p.trim(), 10));
        if (!isNaN(parts[0]) && !isNaN(parts[1])) {
          allowedSectionNumbers = new Set();
          for (let i = parts[0]; i <= parts[1]; i++) allowedSectionNumbers.add(i);
        }
      } else {
        const num = parseInt(clean, 10);
        if (!isNaN(num)) allowedSectionNumbers = new Set([num]);
      }
    }
  }

  // 1. Check exact course + component + cluster + sectionFilter
  let matched = allocations.filter(a => {
    const codeMatch = a.course_code === subjectCode || a.course_code.trim() === subjectCode.trim();
    const compMatch = !component || a.component === component;
    const clusterMatch = !normalizedCluster || a.cluster_id === normalizedCluster || a.cluster_id === 'NA' || !a.cluster_id;
    const sectionMatch = !allowedSectionNumbers || allowedSectionNumbers.has(a.section_number);
    return codeMatch && compMatch && clusterMatch && sectionMatch;
  });

  // 2. If no match with sectionFilter, check course + component + cluster without sectionFilter (using true allocated section)
  if (matched.length === 0 && allowedSectionNumbers) {
    matched = allocations.filter(a => {
      const codeMatch = a.course_code === subjectCode || a.course_code.trim() === subjectCode.trim();
      const compMatch = !component || a.component === component;
      const clusterMatch = !normalizedCluster || a.cluster_id === normalizedCluster || a.cluster_id === 'NA' || !a.cluster_id;
      return codeMatch && compMatch && clusterMatch;
    });
  }

  // 3. If still no direct cluster matches, check across all clusters for this subject and component (respecting sectionFilter if given)
  if (matched.length === 0) {
    matched = allocations.filter(a => {
      const codeMatch = a.course_code === subjectCode || a.course_code.trim() === subjectCode.trim();
      const compMatch = !component || a.component === component;
      const sectionMatch = !allowedSectionNumbers || allowedSectionNumbers.has(a.section_number);
      return codeMatch && compMatch && sectionMatch;
    });
  }

  // 4. If still no matches with sectionFilter across clusters, check across all clusters without sectionFilter
  if (matched.length === 0 && allowedSectionNumbers) {
    matched = allocations.filter(a => {
      const codeMatch = a.course_code === subjectCode || a.course_code.trim() === subjectCode.trim();
      const compMatch = !component || a.component === component;
      return codeMatch && compMatch;
    });
  }

  // If still no matches (e.g. subjects without pre-allocated faculty in workbook), generate deterministic section offerings from qualified faculty
  if (matched.length === 0) {
    let hash = 0;
    for (let i = 0; i < subjectCode.length; i++) {
      hash = ((hash << 5) - hash) + subjectCode.charCodeAt(i);
    }
    hash = Math.abs(hash);

    const qualifiedFaculty = faculty.filter(f => !component || f.components.includes(component));
    const pool = qualifiedFaculty.length > 0 ? qualifiedFaculty : faculty;
    const baseSecOffset = normalizedCluster === "Cluster-1" ? 1 : 51;

    const syntheticAllocations = [];
    const count = Math.min(8, pool.length);
    for (let i = 0; i < count; i++) {
      const fac = pool[(hash + i * 17) % pool.length];
      const secNum = baseSecOffset + i;
      syntheticAllocations.push({
        faculty_id: fac.id,
        faculty_name: fac.name,
        section_id: `S-${secNum}`,
        section_number: secNum,
        component: component || "L",
        designation: fac.designation || "Assistant Professor",
        department: fac.department || "Computer Science & Engineering",
      });
    }
    matched = syntheticAllocations;
  }

  // Sort by section_number ascending, then faculty name
  matched.sort((a, b) => (a.section_number - b.section_number) || a.faculty_name.localeCompare(b.faculty_name));

  // Deduplicate by faculty_id + section_id + component
  const seen = new Set();
  const result = [];
  for (const m of matched) {
    const key = `${m.faculty_id}-${m.section_id}-${m.component}`;
    if (!seen.has(key)) {
      seen.add(key);
      result.push({
        id: m.faculty_id,
        emp_id: m.faculty_id,
        name: m.faculty_name,
        section_id: m.section_id,
        section_number: m.section_number,
        component: m.component,
        designation: m.designation,
        department: m.department,
        displayLabel: `${m.section_id} • ${m.faculty_name} (Emp ID: ${m.faculty_id})`,
      });
    }
  }

  return result;
}

export function sectionFor(subjectCode, facultyId, component, cluster = "Cluster 2") {
  if (!facultyId) return "";
  const normalizedCluster = cluster === "Cluster 1" || cluster === "C1" ? "Cluster-1" :
                            cluster === "Cluster 2" || cluster === "C2" ? "Cluster-2" : cluster;

  const match = allocations.find(a => 
    a.faculty_id === facultyId &&
    (!subjectCode || a.course_code === subjectCode || a.course_code.trim() === subjectCode.trim()) &&
    (!component || a.component === component) &&
    (!normalizedCluster || a.cluster_id === normalizedCluster || a.cluster_id === 'NA')
  );

  if (match) {
    return match.section_id;
  }

  // Fallback match by facultyId and component
  const fallback = allocations.find(a => a.faculty_id === facultyId && (!component || a.component === component));
  if (fallback) return fallback.section_id;

  return "S-1";
}

export function sectionBase(section = "") {
  return String(section).match(/\d+/)?.[0] || "";
}

/**
 * Returns allocated faculty members for a given section in a sub-component.
 * If letter A, B, C is passed, returns the corresponding allocated faculty member.
 */
export function getSubSectionFaculty(subjectCode, secNum, subLetter, component = "S") {
  if (!secNum) return null;
  const cleanSec = parseInt(String(secNum).replace(/\D/g, ''), 10);
  const targetSecId = `S-${cleanSec}`;

  // Find real allocated faculty in this section and component
  const pool = allocations.filter(a => 
    (!subjectCode || a.course_code === subjectCode || a.course_code.trim() === subjectCode.trim()) &&
    a.section_number === cleanSec &&
    (!component || a.component === component)
  );

  const subIdx = subLetter ? subLetter.toUpperCase().charCodeAt(0) - 65 : 0; // A=0, B=1, C=2
  if (pool.length > 0) {
    const matchedAlloc = pool[subIdx % pool.length];
    return {
      id: matchedAlloc.faculty_id,
      emp_id: matchedAlloc.faculty_id,
      name: matchedAlloc.faculty_name,
      section_id: matchedAlloc.section_id,
      designation: matchedAlloc.designation,
      department: matchedAlloc.department,
    };
  }

  // Fallback to general faculty pool
  const qualified = faculty.filter(f => !component || f.components.includes(component));
  const fallbackPool = qualified.length > 0 ? qualified : faculty;
  const baseOffset = (cleanSec * 3 + Math.floor(cleanSec / 2)) % fallbackPool.length;
  const index = (baseOffset + (subIdx >= 0 ? subIdx : 0)) % fallbackPool.length;
  return fallbackPool[index];
}
